import { PHYSICS } from './tops.js';

/**
 * Symmetric-top inspired arcade physics.
 *
 * Real tops stay up because gravity torque τ is perpendicular to angular
 * momentum L ≈ Iω: τ changes the *direction* of L (precession) instead of
 * immediately tipping the axis over. Precession rate Ω ≈ τ/L — faster spin
 * → larger L → slower, stabler precession. When L is small, gravity wins
 * and the lean grows (fall). Nutation is modeled as lean-rate spring/damping.
 */
export class TopPhysics {
  constructor(top) {
    this.applyTop(top);
    this.reset();
  }

  applyTop(top) {
    this.top = top;
    this.friction = top.friction;
    this.mass = top.mass;
  }

  reset() {
    this.rpm = 0;
    this.angle = 0;
    this.leanX = 0;
    this.leanY = 0;
    this.leanVX = 0;
    this.leanVY = 0;
    this.wobble = 0;
    this.alive = false;
    this.fallen = false;
    this.spinTime = 0;
    this.maxRpm = 0;
    this.lastFallenAt = 0;
  }

  whip(velocity = 0.85) {
    if (this.fallen) this.revive();
    const boost = (PHYSICS.whipBoost / this.mass) * Math.min(1.3, Math.max(0.4, velocity));
    this.rpm = Math.min(PHYSICS.maxRpm, this.rpm + boost);
    this.alive = true;
    this.fallen = false;
    this.maxRpm = Math.max(this.maxRpm, this.rpm);
  }

  tap(velocity = 0.85) {
    if (this.fallen) {
      this.revive();
      this.rpm = Math.min(PHYSICS.maxRpm, this.rpm + PHYSICS.tapBoost * 0.6);
      return;
    }
    const boost = (PHYSICS.tapBoost / this.mass) * Math.min(1.2, Math.max(0.35, velocity));
    this.rpm = Math.min(PHYSICS.maxRpm, this.rpm + boost);
    this.leanX *= 0.72;
    this.leanY *= 0.72;
    this.leanVX *= 0.5;
    this.leanVY *= 0.5;
    this.alive = true;
    this.maxRpm = Math.max(this.maxRpm, this.rpm);
  }

  revive() {
    this.fallen = false;
    this.alive = true;
    this.leanX = 0;
    this.leanY = 0;
    this.leanVX = 0;
    this.leanVY = 0;
    this.wobble = 0;
    this.spinTime = 0;
  }

  upright() {
    this.leanX = 0;
    this.leanY = 0;
    this.leanVX = 0;
    this.leanVY = 0;
    this.wobble *= 0.3;
    if (this.fallen && this.rpm > PHYSICS.minRpmAlive) {
      this.fallen = false;
      this.alive = true;
    }
  }

  lean(dx, dy) {
    if (this.fallen) return;
    this.leanX = clamp(this.leanX + dx, -40, 40);
    this.leanY = clamp(this.leanY + dy, -40, 40);
    // Impulse seeds nutation / tip-out response
    this.leanVX += dx * 2.2;
    this.leanVY += dy * 2.2;
  }

  /**
   * @param {number} dt seconds
   */
  update(dt) {
    if (this.fallen) {
      this.rpm = Math.max(0, this.rpm * Math.pow(0.9, dt * 60));
      this.wobble = Math.min(1, this.wobble + dt * 0.4);
      return this.snapshot();
    }

    if (this.rpm > 1) {
      this.alive = true;
      this.spinTime += dt;

      const omega = (this.rpm / 60) * Math.PI * 2;
      this.angle += omega * dt;

      const I = PHYSICS.inertiaBase * this.mass;
      const L = Math.max(PHYSICS.Lmin, I * omega);

      let leanMag = Math.hypot(this.leanX, this.leanY);
      // Map arcade lean units → tip angle θ (0 … ~55°)
      const theta = (leanMag / 40) * (Math.PI * 0.3);
      const sinT = Math.sin(Math.max(theta, 0.002));

      // Tip friction: more lean → more energy loss (slipping contact)
      const leanDrag = 1 - Math.min(0.05, leanMag * 0.001);
      this.rpm *= Math.pow(this.friction * leanDrag, dt * 60);

      // Gravity torque τ ∝ m sinθ ; precession Ω ≈ τ / L
      const tau = PHYSICS.gravityTorque * this.mass * sinT;
      const Omega = (PHYSICS.precessionGain * tau) / L;

      if (leanMag > 0.2) {
        const c = Math.cos(Omega * dt);
        const s = Math.sin(Omega * dt);
        const lx = this.leanX;
        const ly = this.leanY;
        this.leanX = lx * c - ly * s;
        this.leanY = lx * s + ly * c;
        leanMag = Math.hypot(this.leanX, this.leanY);
      }

      // Radial lean dynamics: gyro restore (∝ L) vs gravity tip-out (∝ τ/L)
      const Lref = I * ((PHYSICS.stabilityRpm / 60) * Math.PI * 2);
      const Lratio = L / Lref;
      const gyro = PHYSICS.gyroStiffness * Math.min(2.2, Lratio);
      const tipOut = PHYSICS.tipGain * this.mass * sinT / Math.max(0.18, Lratio);

      let ux = 0;
      let uy = 0;
      if (leanMag > 0.08) {
        ux = this.leanX / leanMag;
        uy = this.leanY / leanMag;
      } else if (this.rpm < PHYSICS.stabilityRpm * 0.55) {
        // Slow nearly-upright tops are weakly unstable (seed tip direction)
        ux = Math.cos(this.angle * 0.37);
        uy = Math.sin(this.angle * 0.37);
      }

      this.leanVX += (-this.leanX * gyro + ux * tipOut) * dt;
      this.leanVY += (-this.leanY * gyro + uy * tipOut) * dt;
      const damp = Math.pow(1 - PHYSICS.nutationDamp, dt * 60);
      this.leanVX *= damp;
      this.leanVY *= damp;

      this.leanX = clamp(this.leanX + this.leanVX * dt, -40, 40);
      this.leanY = clamp(this.leanY + this.leanVY * dt, -40, 40);
      leanMag = Math.hypot(this.leanX, this.leanY);

      // Visible wobble tracks nutation energy + low-L lean
      const nutation = Math.min(1, Math.hypot(this.leanVX, this.leanVY) / 80);
      const wobbleTarget =
        nutation * 0.65 + (leanMag / 40) * (1 - Math.min(1, Lratio)) * 0.55;
      this.wobble += (wobbleTarget - this.wobble) * Math.min(1, dt * 5);

      this.maxRpm = Math.max(this.maxRpm, this.rpm);

      if (this.rpm < PHYSICS.minRpmAlive && leanMag > PHYSICS.fallLean * 0.5) {
        this.fall();
      } else if (this.rpm < PHYSICS.minRpmAlive * 0.45) {
        this.fall();
      } else if (leanMag > PHYSICS.fallLean && this.rpm < PHYSICS.stabilityRpm * 0.65) {
        this.fall();
      }
    } else {
      this.rpm = 0;
      this.alive = false;
      this.leanVX *= 0.9;
      this.leanVY *= 0.9;
      this.wobble *= 0.95;
    }

    return this.snapshot();
  }

  fall() {
    if (this.fallen) return;
    this.fallen = true;
    this.alive = false;
    this.leanVX = 0;
    this.leanVY = 0;
    this.lastFallenAt = Date.now();
  }

  snapshot() {
    return {
      rpm: this.rpm,
      angle: this.angle,
      leanX: this.leanX,
      leanY: this.leanY,
      leanMag: Math.hypot(this.leanX, this.leanY),
      wobble: this.wobble,
      alive: this.alive,
      fallen: this.fallen,
      spinTime: this.spinTime,
      maxRpm: this.maxRpm,
    };
  }
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}
